package prompt

import (
	"encoding/json"
	"os"
	"regexp"
	"strconv"
	"testing"

	"3gpp-mcp-bench/internal/teleqna"
)

// The golden file is generated by running netop-team/TeleQnA's own
// evaluation_tools.py logic over real questions:
//
//	questions_only = deepcopy(questions_dict)
//	questions_only[q].pop("answer")            # explanation too, when present
//	user_prompt = "Here are the questions: \n " + json.dumps(questions_only)
//
// so this test says the harness sends the bytes upstream would send, not merely
// something in the same shape. Regenerate it with the snippet in the repository
// README if TeleQnA ever changes.
func TestFormatMatchesUpstreamBytes(t *testing.T) {
	data, err := os.ReadFile("testdata/upstream_user_prompt.json")
	if err != nil {
		t.Fatal(err)
	}
	var cases []struct {
		ID     string         `json:"id"`
		Fields map[string]any `json:"fields"`
		Want   string         `json:"want"`
	}
	if err := json.Unmarshal(data, &cases); err != nil {
		t.Fatal(err)
	}
	if len(cases) == 0 {
		t.Fatal("no golden cases")
	}

	optionKey := regexp.MustCompile(`^option (\d+)$`)
	for _, c := range cases {
		t.Run(c.ID, func(t *testing.T) {
			q := teleqna.Question{ID: c.ID, Options: map[int]string{}}
			q.Text, _ = c.Fields["question"].(string)
			q.Category, _ = c.Fields["category"].(string)
			for k, v := range c.Fields {
				if mm := optionKey.FindStringSubmatch(k); mm != nil {
					n, _ := strconv.Atoi(mm[1])
					q.Options[n], _ = v.(string)
				}
			}
			if got := formatTeleQnA(q); got != c.Want {
				t.Errorf("user message differs from upstream:\n got %q\nwant %q", got, c.Want)
			}
		})
	}
}
